-- 1. Bổ sung các cột vào bảng vocabularies nếu chưa tồn tại
ALTER TABLE vocabularies ADD COLUMN IF NOT EXISTS ipa text;
ALTER TABLE vocabularies ADD COLUMN IF NOT EXISTS part_of_speech text;
ALTER TABLE vocabularies ADD COLUMN IF NOT EXISTS example_en text;
ALTER TABLE vocabularies ADD COLUMN IF NOT EXISTS example_vi text;
ALTER TABLE vocabularies ADD COLUMN IF NOT EXISTS topic text;

-- 2. Tạo chỉ mục Unique trên LOWER(word) để tránh lỗi trùng lặp khi chạy lại
CREATE UNIQUE INDEX IF NOT EXISTS vocabularies_word_lower_idx ON vocabularies (LOWER(word));

-- 3. Chèn dữ liệu theo các batch 150 từ với mệnh đề ON CONFLICT DO NOTHING
